content = []
for ref, row in zip(references, copy):
    name, intro, serving = row.split('|')
    assert name == ref['name'], (name, ref['name'])
    text = ref['sourceText']
    ingredients = text.split('Состав:', 1)[1].split('Инструкция по приготовлению и хранению:', 1)[0].strip() if 'Состав:' in text else ''
    # Keep only factual ingredient declarations; manufacturer marketing stays in research.
    ingredients = re.sub(r'\s+', ' ', ingredients)
    needs_proof = 'Требуется расстойка' in text.split('Состав:')[0]
    prebaked = 'Предварительно выпеченный' in text.split('Состав:')[0]
    content.append({'id': ref['id'], 'intro': intro, 'serving': serving,
                    'ingredients': ingredients, 'needsProofing': needs_proof,
                    'prebaked': prebaked, 'sourceUrl': ref['sourceUrl'], 'checkedOn': ref['checkedOn']})
(ROOT / 'src/data/supplier-content.json').write_text(json.dumps(content, ensure_ascii=False, indent=2) + '\n')
print(f'Prepared {len(content)} factual editorial records')
